package work.chncyl.base.global.security.utils;

import cn.hutool.core.collection.CollUtil;
import cn.hutool.core.util.StrUtil;
import work.chncyl.base.global.redis.RedisUtils;
import work.chncyl.base.global.security.entity.UserBasicInfo;

import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

import static work.chncyl.base.global.Constants.USER_BASIC_INFO_KEY;
import static work.chncyl.base.global.Constants.USER_PERMISSIONS_KEY;

/**
 * 权限缓存管理工具类
 * 用于处理权限变更时的缓存失效和更新
 */
public class PermissionCacheUtil {

    /**
     * 根据用户ID清除权限缓存
     * @param userId 用户ID
     */
    public static void clearUserPermissionCache(String userId) {
        if (StrUtil.isBlank(userId)) {
            return;
        }
        
        // 查找所有包含该用户ID的缓存键
        Set<String> keys = RedisUtils.keys(USER_BASIC_INFO_KEY + "*");
        if (CollUtil.isEmpty(keys)) {
            return;
        }
        
        // 过滤出包含指定用户ID的缓存键
        List<String> userKeys = keys.stream()
                .filter(key -> {
                    UserBasicInfo userBasicInfo = RedisUtils.get(key);
                    return userBasicInfo != null && userId.equals(userBasicInfo.getUserId());
                })
                .map(key -> key.replace(USER_BASIC_INFO_KEY, ""))
                .collect(Collectors.toList());
        
        // 清除相关缓存
        userKeys.forEach(jwtId -> {
            RedisUtils.delete(USER_BASIC_INFO_KEY + jwtId);
            RedisUtils.delete(USER_PERMISSIONS_KEY + jwtId);
        });
    }

    /**
     * 根据角色ID清除权限缓存
     * @param roleId 角色ID
     */
    public static void clearRolePermissionCache(String roleId) {
        if (StrUtil.isBlank(roleId)) {
            return;
        }
        
        // 查找所有包含该角色ID的缓存键
        Set<String> keys = RedisUtils.keys(USER_BASIC_INFO_KEY + "*");
        if (CollUtil.isEmpty(keys)) {
            return;
        }
        
        // 过滤出包含指定角色ID的缓存键
        List<String> roleKeys = keys.stream()
                .filter(key -> {
                    UserBasicInfo userBasicInfo = RedisUtils.get(key);
                    return userBasicInfo != null && 
                           userBasicInfo.getRoleIds() != null &&
                           userBasicInfo.getRoleIds().contains(roleId);
                })
                .map(key -> key.replace(USER_BASIC_INFO_KEY, ""))
                .collect(Collectors.toList());
        
        // 清除相关缓存
        roleKeys.forEach(jwtId -> {
            RedisUtils.delete(USER_BASIC_INFO_KEY + jwtId);
            RedisUtils.delete(USER_PERMISSIONS_KEY + jwtId);
        });
    }

    /**
     * 更新用户权限缓存
     * @param jwtId JWT ID
     * @param newPermissions 新的权限列表
     */
    public static void updateUserPermissions(String jwtId, List<String> newPermissions) {
        if (StrUtil.isBlank(jwtId) || CollUtil.isEmpty(newPermissions)) {
            return;
        }
        
        // 更新权限缓存
        RedisUtils.set(USER_PERMISSIONS_KEY + jwtId, newPermissions);
        
        // 获取原有的过期时间并设置
        Long expireTime = RedisUtils.getExpire(USER_BASIC_INFO_KEY + jwtId);
        if (expireTime != null && expireTime > 0) {
            RedisUtils.expire(USER_PERMISSIONS_KEY + jwtId, expireTime);
        }
    }
}
